window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"QyMJqIFJjVU","speaker":"Deogratius Ndejembi","role":"Vice President","country":"Tanzania","region":"Africa","url":"https://www.youtube.com/watch?v=QyMJqIFJjVU","date":"20260922","title":"🇹🇿  Tanzania - Vice President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":987,"words":1718,"counts":{"claims":23,"promises":2,"attacks":0},"topics":[{"topic":"UN reform","share":0.0896,"seconds":88},{"topic":"UN sanctions","share":0.0841,"seconds":83},{"topic":"UN Security Council","share":0.0825,"seconds":81},{"topic":"Tanzania development","share":0.0729,"seconds":72},{"topic":"Tanzania UN candidacy","share":0.0703,"seconds":69},{"topic":"Tanzania energy","share":0.0697,"seconds":69},{"topic":"UNGA 81st session","share":0.0694,"seconds":68},{"topic":"Israel-Palestine","share":0.0691,"seconds":68},{"topic":"climate finance","share":0.0687,"seconds":68},{"topic":"UN Charter","share":0.0673,"seconds":66},{"topic":"Tanzania maternal health","share":0.0659,"seconds":65},{"topic":"Tanzania finance","share":0.0653,"seconds":64},{"topic":"unilateral sanctions","share":0.064,"seconds":63},{"topic":"sea level rise","share":0.0612,"seconds":60}],"timeline":[[4,70,null],[70,139,"UNGA 81st session"],[140,229,"UN reform"],[230,302,"Tanzania development"],[303,368,"Tanzania finance"],[370,435,"Tanzania maternal health"],[436,504,"climate finance"],[506,575,"Tanzania energy"],[576,637,"sea level rise"],[638,702,"unilateral sanctions"],[703,786,"UN sanctions"],[788,870,"UN Security Council"],[872,941,"Tanzania UN candidacy"],[943,1011,"Israel-Palestine"],[1012,1081,null],[1083,1149,"UN Charter"],[1150,1169,null]],"stances":{"UNGA 81st session":"Deogratius Ndejembi congratulates the President on their election and expresses confidence in their ability to guide the proceedings.","UN reform":"Deogratius Ndejembi argues that the UN must be reformed to meet current realities and go beyond administrative efficiency to ensure effectiveness, accountability, and representativeness.","Tanzania development":"Deogratius Ndejembi states that Tanzania remains committed to the 2030 agenda and is investing in people, infrastructure, and innovation to improve SDG progress.","Tanzania finance":"Deogratius Ndejembi argues that international financial architecture must be reformed to support developing countries and that political commitment is essential for focused investment.","Tanzania maternal health":"Deogratius Ndejembi states that Tanzania has achieved significant reductions in maternal and child mortality through expanded facility delivery and people-centered development, and aims to advance three zero goals.","climate finance":"Deogratius Ndejembi states that global climate efforts are being frustrated by the withdrawal of financial contributions and urges increased long-term concessional financing.","Tanzania energy":"Deogratius Ndejembi outlines Tanzania's specific renewable energy projects and clean cooking targets while requesting climate financing in the form of grants.","sea level rise":"Deogratius Ndejembi supports a workable solution to sea level rise and welcomes the UN declaration on the topic.","unilateral sanctions":"Tanzania opposes the use of unilateral sanctions and coercive measures against member states while affirming solidarity with Cuba, Zimbabwe, and other affected nations.","UN sanctions":"Deogratius Ndejembi calls for the immediate lifting of measures causing hardship and urges reaffirmation of multilateralism.","UN Security Council":"Deogratius Ndejembi states that Tanzania is committed to the UN Security Council's role in maintaining international peace and highlights past contributions as a member.","Tanzania UN candidacy":"Deogratius Ndejembi announces Tanzania's candidacy for the council and outlines priorities including peacekeeping reform and support for women and youth.","Israel-Palestine":"Deogratius Ndejembi states that Tanzania remains firmly committed to the two-state solution and reaffirms the right of the Palestinian people to self-determination.","UN Charter":"Deogratius Ndejembi states that Tanzania believes respecting and living by the UN Charter is necessary to honor the past and build a safer future."},"claims":[{"t":120,"quote":"About 80 years ago, the United Nation was founded in San Francisco on a simple but enduring principle that nations can prevent war and advance peace through trust, collective action, and respect the UN charter.","topic":"UNGA 81st session","kind":"fact"},{"t":140,"quote":"Today, war and insecurity are not only existential threats to our survival, but a range of challenges, including climate change, pandemics, ungoverned artificial and energy insecurity, just to mention a few.","topic":"UN reform","kind":"fact"},{"t":200,"quote":"I commend our illustrious secretary general, his excellency Antonio Gutirez for championing the UN80 initiative that aims to advance the transformation","topic":"UN reform","kind":"self_credit"},{"t":252,"quote":"While we're a few years away from year progress towards attainment of the SDGs is still unimpressive.","topic":"Tanzania development","kind":"fact"},{"t":274,"quote":"Tanzania remains committed and has made strides in implementing the 2030 agenda.","topic":"Tanzania development","kind":"self_credit"},{"t":322,"quote":"Currently, when developing countries are accelerating progress, they are restricted by higher borrowing costs, rising debt burdens, and limited access to affordable long-term","topic":"Tanzania finance","kind":"fact"},{"t":373,"quote":"reducing maternal and child mortality by expanding facility delivery from 51% in 2015 to 81% in 2022","topic":"Tanzania maternal health","kind":"number"},{"t":414,"quote":"Tanzania reduced maternal deaths by 80% in just seven","topic":"Tanzania maternal health","kind":"number"},{"t":476,"quote":"Global efforts to address climate challenges are being frustrated by withdrawal of financial contributions supporting climate adaptation measures and initiatives by international and regional institutions as well as individual states.","topic":"climate finance","kind":"fact"},{"t":517,"quote":"implementation of the national renewable strategy that comprises of a 2,115 megawatt Julius Ner hydro power project of 650 megawatts of solar and wind power 130 megawatts of geothermal uh power projects","topic":"Tanzania energy","kind":"number"},{"t":539,"quote":"national clean cooking strategy which aims to ensure that 80% of households adopt clean cooking by the year 2034","topic":"Tanzania energy","kind":"number"},{"t":579,"quote":"Tanzania joins small island and coastal states in pushing for a workable solution to address sea level rises.","topic":"sea level rise","kind":"fact"},{"t":588,"quote":"We commend the president for conveying today the high level event addressing the existential threats posed by sea level rise","topic":"sea level rise","kind":"fact"},{"t":638,"quote":"Timely and urgent action is needed to safeguard the future of our coastal communities and island nations.","topic":"unilateral sanctions","kind":"fact"},{"t":677,"quote":"Tanzania reaffirms its position to oppose the use of such coercive measures against any member state","topic":"unilateral sanctions","kind":"fact"},{"t":703,"quote":"We call for an immediate and unequivocal lifting of these measures that cause hardship, constrain development, and obstruct full enjoyment of human rights.","topic":"UN sanctions","kind":"fact"},{"t":726,"quote":"The United Nations through its charter has remained central to international efforts to maintain peace and security, uphold international law, promote conditions conducive to development.","topic":"UN sanctions","kind":"fact"},{"t":805,"quote":"Our commitment is demonstrated by our two terms of service on the Security Council during which we made substantive contributions to such cause.","topic":"UN Security Council","kind":"fact"},{"t":819,"quote":"Notable achievements include the adoption of security council resol resolution 1653 in the year 20 uh 20006 on the great lakes region","topic":"UN Security Council","kind":"fact"},{"t":872,"quote":"I therefore seize this opportunity to formally announce our candidature.","topic":"Tanzania UN candidacy","kind":"fact"},{"t":879,"quote":"During our tenure in the council, we will put forward and prioritize deliberations on matters vital to the maintainance of international peace and security such as preventive diplomacy and the peaceful settlement of disputes.","topic":"Tanzania UN candidacy","kind":"fact"},{"t":985,"quote":"We have been consistent on this for the past 50 years.","topic":"Israel-Palestine","kind":"number"},{"t":1117,"quote":"As we take stock of its invaluable contribution to the advancement of humanity, maintainance of international peace and security, social economic progress and sustained development over the past 81 years.","topic":"UN Charter","kind":"fact"}],"promises":[{"t":423,"quote":"We now aim to advance the three zeros. Zero preventable maternal and child deaths, zero home deliveries, and zero unvaccinated children.","topic":"Tanzania maternal health","kind":"promise"},{"t":905,"quote":"In the coming days, we will engage with each one of you and present our vision and respectfully seek your valued support to enable Tanzania to serve with a strong African voice, principled leadership, and unwavering commitment to international peace","topic":"Tanzania UN candidacy","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":null,"text":"The assembly will now hear an address by his excellency vice president of the United Republic of I request protocol to escort his excellency and invite him to address the Your Excellency Dr. Halier Rahman, President of the 81st session of the United Nations General Assembly. Your Excellency Antonio Gutirez, Secretary General of the United Nations. Excellencies, heads of state and government, distinguished delegates, good afternoon. It is indeed a great honor and privilege to address this assembly on behalf of her excellency Dr."},{"t":70,"topic":"UNGA 81st session","text":"Samir Sulu Hassan, President of the United Republic of Tanzania. Her excellency, the president, asked me to convey her fraternal greetings and best wishes for the success of this session. Mr. President, allow me to congratulate you on your election to preside over the 81st session of the United Nations General Your immense experience and diplomatic skills give us confidence in your ability to guide the proceedings of this session successfully. Your election is also a fitting tribute to the great country Bangladesh with which Tanzania enjoys excellent Mr. president. About 80 years ago, the United Nation was founded in San Francisco on a simple but enduring principle that nations can prevent war and advance peace through trust, collective action, and respect the UN charter."},{"t":140,"topic":"UN reform","text":"Today, war and insecurity are not only existential threats to our survival, but a range of challenges, including climate change, pandemics, ungoverned artificial and energy insecurity, just to mention a few. These challenges should remind us of a need for a stronger and much more coordinated United Nations. Therefore, the theme of this session that is restoring trust, managing transformation, a united nation that delivers for all is timely for it requires us to revert to the founding principles of maintaining peace and restoring trust. Managing transformation requires reforming the UN to meet the realities of our time. In that regard, I commend our illustrious secretary general, his excellency Antonio Gutirez for championing the UN80 initiative that aims to advance the transformation In our opinion, the UN80 initiative must go beyond administrative efficiency to include overall organizational effectiveness, accountability, and representativeness for the United Nation to be able to deliver for all."},{"t":230,"topic":"Tanzania development","text":"Further, the transformation must be undertaken with utmost caution to avoid going off track on the development pillar and incapacitating the United Nation country offices and programs. Mr. President, excellencies and distinguished delegates. While we're a few years away from year progress towards attainment of the SDGs is still unimpressive. Given this situation, we need to improve our execution and ensure that every cent invested delivers results. Tanzania remains committed and has made strides in implementing the 2030 agenda. Tanzania's development vision 2050 aims to build an inclusive and competitive economy that ensures quality of life for We're investing in our people, productive infrastructure, technology, and innovation while creating greater opportunity for women and young people."},{"t":303,"topic":"Tanzania finance","text":"Our ambition is to transform economic growth into lasting improvements for people's lives. These ambitions may not be realized if the international financial architecture is not made to work for development. Currently, when developing countries are accelerating progress, they are restricted by higher borrowing costs, rising debt burdens, and limited access to affordable long-term Tanzania stresses that improvements must be made to ensure expansion of concessional financing, mobilization of private investment, improved access to development and climate finance and giving developing countries a stronger voice in the global financial decision It is without a doubt that political commitment is paramount in undertaking focused investment."},{"t":370,"topic":"Tanzania maternal health","text":"In that, Tanzania has made significant strides in reducing maternal and child mortality by expanding facility delivery from 51% in 2015 to 81% in 2022. Our experience on this demonstrates that when invest when we invest in feasible projects and remain people centered development can move from promises to measurable results. It is in this spirit that her excellency president Samya Sulu Hassan accepted the responsibility of championing maternal and child health for the African Union. Under her leadership, Tanzania reduced maternal deaths by 80% in just seven We now aim to advance the three zeros. Zero preventable maternal and child deaths, zero home deliveries, and zero unvaccinated children."},{"t":436,"topic":"climate finance","text":"Our experience shows that this is an agenda that Africa can successfully achieve, but it will require sustained political leadership, adequate financing, and stronger partnerships. We therefore urge the international community to join us in giving this agenda a big push. our efforts to address climate related challenges continue to face obstacles mainly from those contributing significantly to greenhouse gas Global efforts to address climate challenges are being frustrated by withdrawal of financial contributions supporting climate adaptation measures and initiatives by international and regional institutions as well as individual states. Let us prioritize delivery on the pledges for climate action by increasing long-term concessional financing and development of newer technologies."},{"t":506,"topic":"Tanzania energy","text":"On this agenda, Tanzania chose to address the just energy transition component through different measures. Some of these measures include implementation of the national renewable strategy that comprises of a 2,115 megawatt Julius Ner hydro power project of 650 megawatts of solar and wind power 130 megawatts of geothermal uh power projects, and the national clean cooking strategy which aims to ensure that 80% of households adopt clean cooking by the year 2034. In our efforts to reduce the use of fossil fuels, we have also opted for the electric railway to link the port of Daris Salam to neighboring countries of Burundi and the Democratic Republic of Congo. We therefore appeal that climate financing be provided as grants and concessional financing to step up efforts on climate action."},{"t":576,"topic":"sea level rise","text":"Mr. President, Tanzania joins small island and coastal states in pushing for a workable solution to address sea level rises. We commend the president for conveying today the high level event addressing the existential threats posed by sea level rise and we look forward to the adoption of the UN declaration on sea level rise which will provide a comprehensive framework for international cooperation scientific advancement adaptation resilience and legal stability. We welcome the declaration's legal affirmation on the stability of maritime zones under United Nation Convention on Law of the Seas and the continuity of statehood even in cases of physical land loss while encouraging strengthened international cooperation and the protection of human rights."},{"t":638,"topic":"unilateral sanctions","text":"Timely and urgent action is needed to safeguard the future of our coastal communities and island nations. global solidarity must be concurrent with respect of each other's sovereignity. Tanzania stands against the proliferating trend of some states to assume the responsibility of policing and imposing unilateral sanctions on others, thus undermining the principles of sovereignity and peaceful As stated previously, Tanzania reaffirms its position to oppose the use of such coercive measures against any member state and reaffirms its unwavering solidarity with Cuba, Zimbabwe, and all other states that are subjected to such unjustifiable constraints. In line with this, our resolve to leave no one behind."},{"t":703,"topic":"UN sanctions","text":"We call for an immediate and unequivocal lifting of these measures that cause hardship, constrain development, and obstruct full enjoyment of human rights. Mr. President, global peace and security are vital for sustainable soioeconomic development. The United Nations through its charter has remained central to international efforts to maintain peace and security, uphold international law, promote conditions conducive to development. despite these longlasting commitments, the persistence of armed conflicts around the world reflect the departure from the purpose and principles of the In addition, there are emerging challenges to the authority of the United Nations Charter and the established principles of international law, often without commensurate These developments underscore the urgent need to reaffirm multilateralism, strengthen respect for international law and reinforce the central role of the United Nations in maintaining international peace and security."},{"t":788,"topic":"UN Security Council","text":"In that regard, Tanzania remains firmly committed to supporting the efforts of the UN Security Council to fulfill its primary responsibility for the maintainance of international peace and Our commitment is demonstrated by our two terms of service on the Security Council during which we made substantive contributions to such cause. Notable achievements include the adoption of security council resol resolution 1653 in the year 20 uh 20006 on the great lakes region and Tanzania's collaboration with Denmark in establishing the peacebuilding building on this record and sustained commitment to I am pleased to inform you that recently the African Union formally took of Tanzanian's candidacy for a non-permanent seat on the UN Security Council for the term 2029 2030 during elections to be held by this assembly in June 2028."},{"t":872,"topic":"Tanzania UN candidacy","text":"I therefore seize this opportunity to formally announce our candidature. During our tenure in the council, we will put forward and prioritize deliberations on matters vital to the maintainance of international peace and security such as preventive diplomacy and the peaceful settlement of disputes. Women in peacekeeping, youth in peace and security, and the reform of the United Nations peacekeeping. In the coming days, we will engage with each one of you and present our vision and respectfully seek your valued support to enable Tanzania to serve with a strong African voice, principled leadership, and unwavering commitment to international peace and Mr. President Tanzania is deeply concerned and saddened by the protracted conflict and humanitarian suffering in Gaza and across the Middle East."},{"t":943,"topic":"Israel-Palestine","text":"We continue to call for the protection of civilians, unhindered humanitarian assistance, and renewed diplomacy towards lasting peace. Tanzania remains firmly committed to the two-state solution with Israel and Palestine living side by side in peace and harmony in accordance with international law and relevant UN We reaffir we reaffirm the right of the Palestinian people to self-determination and believe that lasting peace must guarantee dignity, security, and legitimate aspiration of both peoples. We have been consistent on this for the past 50 years. For us, this is a matter of our foreign principle. Mr. President, on behalf of the people of the United Republic of Tanzania, I wish to pay tribute to his excellency Antonio Gutirez as he concludes his distinguished tenure as Secretary General of the United Nations."},{"t":1012,"topic":null,"text":"During his tenure, he steered the UN through an exceptionally challenging periods marked by conflicts, geopolitical tensions, the coid9 pandemic, climate emergencies, and growing pressure on multilateralism. In all these situations, he remained firm and undeterred. Tanzania appreciates his support for Africa's aspirations for peace, sustainable development, climate justice, and a fairer international financial architecture as well as his personal engagement with our country. Similar accolades are for Ambassador Amina Muhammad, Deputy Secretary General, who has played a pivotal role in advancing the SDGs, advocacy for women, children, and those whose voices are too often unheard."},{"t":1083,"topic":"UN Charter","text":"We shall miss your contribution, but Africa is proud to welcome its own daughter back home. To both of you, we wish you every success and fulfillment in the years Mr. President, in conclusion, I wish to underscore that the UN must not merely reflect on the balance of power, but serve as a platform for justice, solidarity, and progress. As we take stock of its invaluable contribution to the advancement of humanity, maintainance of international peace and security, social economic progress and sustained development over the past 81 years. Let us be reminded that there are more mountains to climb and milestones to accomplish. Tanzania believes that it is only by respecting and living by the charter that we can honor the past and build a safer and better future for all."},{"t":1150,"topic":null,"text":"Thank you for your attention. Asante Sana. On behalf of the assembly, I wish to thank the vice president of the United Republic of Tanzania."}],"compare":[{"topic":"UN & its reform","share":0.393,"mean":0.2038,"rank":20,"others":170},{"topic":"Climate Change","share":0.1299,"mean":0.0423,"rank":22,"others":77},{"topic":"Israel–Palestine","share":0.0691,"mean":0.0523,"rank":54,"others":76},{"topic":"Sanctions","share":0.064,"mean":0.0028,"rank":4,"others":5}]};
